function toggleFulfillmentMode(e,t){if(!e)return;const l=e.querySelector(".view"),n=e.querySelector(".edit");if(!l||!n)return;const o=n.querySelector(".wpo-aom-fulfillment-actions");"edit"===t?(n.style.display="flex",l.style.display="none",o&&(o.style.display="flex")):"view"===t&&(l.style.display="flex",n.style.display="none",o&&(o.style.display="none"))}document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".wpo-aom-edit-fulfillment").forEach(function(e){e.addEventListener("click",function(){toggleFulfillmentMode(e.closest(".wpo-aom-fulfillment"),"edit")})});document.querySelectorAll(".wpo-aom-cancel-fulfillment").forEach(function(e){e.addEventListener("click",function(){toggleFulfillmentMode(e.closest(".wpo-aom-fulfillment"),"view")})});document.querySelectorAll(".wpo-aom-save-fulfillment").forEach(function(e){e.addEventListener("click",function(){const t=e.closest(".wpo-aom-fulfillment"),l=e.getAttribute("data-item-id"),n=e.getAttribute("data-fulfillment-id"),o=t.querySelector(".wpo-aom-fulfillment-quantity");if(!o)return;const i=o.value,a=new FormData;a.append("action","wpo_aom_save_fulfillment"),a.append("nonce",WPO_AOM_OrderEdit.nonce),a.append("item_id",l),a.append("fulfillment_id",n),a.append("quantity",i),e.disabled=!0,fetch(ajaxurl,{method:"POST",body:a}).then(function(e){return e.json()}).then(function(e){if(e.success){const l=t.querySelector(".view");if(l&&e.data.html){const t=l.querySelector(".wpo-aom-tag");t&&(t.outerHTML=e.data.html)}toggleFulfillmentMode(t,"view"),o.value=i}else alert(e.data.message||"Error saving fulfillment")}).catch(function(e){console.error("Error:",e),alert("Error saving fulfillment")}).finally(function(){e.disabled=!1})})})});